import React, { useState } from "react";
import SearchBar from "./components/SearchBar";

function Home() {
  const [homes, setHomes] = useState([]);

  return (
    <div
      className="min-h-screen bg-gray-900 text-white flex flex-col items-center justify-center p-4"
      style={{
        backgroundImage: "url('/path-to-your-background-image.jpg')",
        backgroundSize: "cover",
        backgroundPosition: "center",
      }}
    >
      <SearchBar setHouses={setHomes} />
      {homes.length === 0 && (
        <div
          style={{
            color: "#ffffff",
            fontSize: "1.2rem",
            marginTop: "0.5rem",
            backgroundColor: "rgba(0, 0, 0, 0.9)",
            padding: "0.5rem",
            borderRadius: "0.3rem",
          }}
        >
          No homes found in that area.
        </div>
      )}
      {homes.length > 0 && (
        <div
          style={{
            color: "#ffffff",
            fontSize: "1.2rem",
            marginTop: "0.5rem",
            backgroundColor: "rgba(0, 0, 0, 0.9)",
            padding: "0.5rem",
            borderRadius: "0.3rem",
          }}
        >
          {homes.length} homes found!
        </div>
      )}
    </div>
  );
}

export default Home;
